using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using SmartWaste.Application.Collection.Interfaces; using SmartWaste.Domain.Common;
namespace SmartWaste.Api.Controllers.Collection;
[ApiController,Route("api/v1/routes"),Authorize] public sealed class RoutesController(IAssignmentReadService service):ControllerBase { [HttpGet("{id:guid}"),Authorize(Roles=AppRoles.WasteOfficer+","+AppRoles.MunicipalManager+","+AppRoles.Driver)] public async Task<IActionResult> Get(Guid id,CancellationToken ct){var user=User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub");var role=User.FindFirstValue(ClaimTypes.Role)??User.FindFirstValue("role");if(!Guid.TryParse(user,out var actor)||role is null)return Unauthorized();return Ok(await service.GetRouteAsync(id,actor,role,ct));} }
